    body: "// Tiles protocol: size (https://dasl.ing/tp-size.html).\n//\n// A tile negotiates how big it is with the context that runs it. The tile\n// asks; the context, which has limits of its own and the last word, grants.\n//\n//   const size = await import('/.well-known/web-tiles/size.js');\n//   const granted = await size.requestSize({ height: 640 });  // { width, height, limits }\n//   size.addSizeHandler(({ width, height, limits }) => { … });  // the context changed it\n//   size.listen();                                            // tell me how big I am now\n//   const stop = size.fitContent();                           // keep my height on my content\n//\n// A manifest that declares `sizing.fit` needs none of this: the runtime\n// measures the tile's content for it (see shuttle.js), with the two functions\n// at the bottom of this file.\n\nconst UP = 'tiles-protocol-up-size-';\nconst DOWN = 'tiles-protocol-down-size-';\nconst ANSWER_MS = 3000;\n\nconst handlers = [];\nconst pending = new Map();\nlet counter = 0;\n\n/** Calls `handler({ width, height, limits })` whenever the context sets the tile's size, asked for or not. */\nexport function addSizeHandler (handler) {\n  if (!handlers.includes(handler)) handlers.push(handler);\n}\n\nexport function removeSizeHandler (handler) {\n  const idx = handlers.indexOf(handler);\n  if (idx >= 0) handlers.splice(idx, 1);\n}\n\nwindow.addEventListener('message', (ev) => {\n  // Grants come from the context, which is our parent, and from no one else.\n  if (ev.source !== window.parent) return;\n  const { action, payload } = ev.data || {};\n  if (action !== `${DOWN}grant` || !payload || typeof payload !== 'object') return;\n  const { id, width, height, limits } = payload;\n  const granted = { width, height, limits: limits || {} };\n  if (id && pending.has(id)) {\n    pending.get(id)(granted);\n    pending.delete(id);\n  }\n  handlers.forEach(h => h(granted));\n});\n\n/** Asks the context to say how big the tile is now; the answer arrives at the size handlers. */\nexport function listen () {\n  window.parent.postMessage({ action: `${UP}ready` }, '*');\n}\n\n/**\n * Asks for a size, in CSS pixels; either dimension may be left out. Resolves\n * with what the context granted, `{ width, height, limits }`, which is the\n * size the tile now has and may not be what it asked for. Rejects if the\n * context does not answer (it may not implement the protocol).\n */\nexport function requestSize (size = {}) {\n  const id = `s${++counter}`;\n  const payload = { id };\n  if (Number.isFinite(size.width)) payload.width = size.width;\n  if (Number.isFinite(size.height)) payload.height = size.height;\n  return new Promise((resolve, reject) => {\n    pending.set(id, resolve);\n    setTimeout(() => {\n      if (!pending.delete(id)) return;\n      reject(new Error('The context did not answer the size request.'));\n    }, ANSWER_MS);\n    window.parent.postMessage({ action: `${UP}request`, payload }, '*');\n  });\n}\n\n/**\n * Keeps the tile's size on its content: asks again whenever the content's\n * size changes. `{ height: true }` by default; `{ width: true }` too for a\n * tile whose root is sized to its content (see `contentSize`). Returns a\n * function that stops it.\n */\nexport function fitContent (dimensions = { height: true }) {\n  return watchContent(document, dimensions, (size) => { requestSize(size).catch(() => {}); });\n}\n\n/**\n * The size of a document's content: the box of its root element. With the\n * default styles that is as tall as the content and as wide as the viewport,\n * so height follows content as it is. For width to follow too, size the root\n * to its content (`html { width: max-content }`). A root given the viewport's\n * height (`height: 100%`, `100vh`) has no content height of its own to report.\n */\nexport function contentSize (doc = document) {\n  const box = doc.documentElement.getBoundingClientRect();\n  return { width: Math.ceil(box.width), height: Math.ceil(box.height) };\n}\n\n/**\n * Calls `report` with the dimensions asked for (`{ width?, height? }`) of a\n * document's content size, now and each time they change. Returns a function\n * that stops it.\n */\nexport function watchContent (doc, dimensions, report) {\n  let last = '';\n  const check = () => {\n    if (!doc.documentElement) return;\n    const size = contentSize(doc);\n    const wanted = {};\n    if (dimensions.width) wanted.width = size.width;\n    if (dimensions.height) wanted.height = size.height;\n    const key = `${wanted.width}x${wanted.height}`;\n    if (key === last || !(wanted.width || wanted.height)) return;\n    last = key;\n    report(wanted);\n  };\n  const observer = new ResizeObserver(check);\n  observer.observe(doc.documentElement);\n  check();\n  return () => observer.disconnect();\n}\n",
